pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(uint160(0xE0A));

    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new C(address(this), 0); vm.stopPrank(); }

    function testFuzz_property(address actor) public {
        // the donator must be a real person (an EOA: no code)
        vm.assume(actor.code.length == 0);
        // the owner (a real person) opens the contract
        vm.deal(owner, 1 ether);
        vm.startPrank(owner, owner);
        c.OpenToThePublic();
        vm.stopPrank();
        // any EAO party can now donate through the open contract
        vm.deal(actor, 1 wei);
        bool ok;
        vm.startPrank(actor, actor);
        try c.donate{value: 0}() { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(ok, "donate by an external party must succeed once the contract is open");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant OWNER = address(uint160(0xE0A));

    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new C(address(this), 0); vm.stopPrank(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != OWNER);
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0); // a real person (EOA), so tx.origin == msg.sender applies
        amount = bound(amount, 0, 100 ether);

        // owner sets the bet limit to the fuzzed amount and opens the contract
        vm.startPrank(OWNER, OWNER);
        c.AdjustBetAmounts(amount);
        c.OpenToThePublic();
        vm.stopPrank();

        // an external EOA party wagers exactly the current bet limit
        vm.deal(actor, amount);
        bool ok;
        vm.startPrank(actor, actor); // msg.sender == tx.origin (onlyRealPeople satisfied)
        try c.wager{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // Rule: once opened, any EAO player's wager succeeds and is recorded.
        assertTrue(ok && c.hasPlayerWagered(actor));
    }
}

