contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function test(uint256 newLimit) public {
		require(address(this) != address(0));
		bool ok;
		(ok, ) = address(c).call(abi.encodeWithSelector(c.AdjustBetAmounts.selector, newLimit));
		assert(!ok && c.currentBetLimit() != newLimit);
	}
}

