contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }
	function checkAdjustDifficultyByNonOwner(uint256 amount) public {
		// The caller (this test contract) is not the owner of c, which was
		// set to the deployer of C in its constructor.
		bool ok;
		(ok, ) = address(c).call(abi.encodeWithSelector(c.AdjustDifficulty.selector, amount));
		// On P this call reverts (onlyOwner holds for msg.sender != owner),
		// so ok must be false. On M the inverted modifier lets the call succeed.
		assert(!ok);
	}
	receive() external payable {}
	fallback() external payable {}
}

